import{_ as i,c as a,o as t,a5 as o}from"./chunks/framework.CxlzjCG8.js";const g=JSON.parse('{"title":"Device information","description":"","frontmatter":{"outline":"deep","order":7},"headers":[],"relativePath":"apps/admin/devices/information.md","filePath":"apps/admin/devices/information.md"}'),n={name:"apps/admin/devices/information.md"};function r(l,e,s,c,d,p){return t(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o('<h1 id="device-information" tabindex="-1">Device information <a class="header-anchor" href="#device-information" aria-label="Permalink to &quot;Device information&quot;">​</a></h1><p>Verbose information about the device, including:</p><ul><li>Overview: General device state information, and summarized device information over time.</li><li>Timeline: A detailed timeline of data received from the device, and received by SIM providers.</li><li>Config Pages: Current config pages applied to the device.</li></ul><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/GnwHbXd.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><p>The top of the overview summarizes the current plan and billing state of the device.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/tIjgUsM.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="metric-summary" tabindex="-1">Metric Summary <a class="header-anchor" href="#metric-summary" aria-label="Permalink to &quot;Metric Summary&quot;">​</a></h2><p>An expandable overview of some device metrics, errors, sends and power usage are then displayed. You can mouse over the graphs to see more details about the data.</p><p>Use the <code>+1 Day</code> and <code>+1 Week</code> buttons to expands the time range of the graph into the past.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/alZiO0u.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>This data is then summarized further with some key metrics.</p><ul><li>Total Time</li><li>Total Points</li><li>Avenge Signal</li><li>Average Points per transmit</li><li>Average Time Between Points</li><li>Average Time Between</li><li>Average Power per Transmit</li><li>Average Power per Point</li><li>Battery percent and voltage at start of the time range.</li><li>Battery percent and voltage at end of the time range.</li><li>Max battery voltage during the time range.</li></ul><p>And a breakdown of the source of locations received during the time range.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/oIgFTmS.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h2><p>The timeline shows a detailed view of events from and related to the device.</p><p>This will poll for new events as they happen, so you should be able to see your device connecting and sending data when active.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/WoevCJG.png" alt="" tabindex="0"><figcaption></figcaption></figure><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>If your device has not recently sent any data, you might find the timeline empty, or timing out.</p></div><h2 id="live" tabindex="-1">Live <a class="header-anchor" href="#live" aria-label="Permalink to &quot;Live&quot;">​</a></h2><p>For devices that make use of V3 messaging, you can also view live data from the device as it is received by the Lightbug platform.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/03/chrome_eEEcyNZDFD.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="config-pages" tabindex="-1">Config Pages <a class="header-anchor" href="#config-pages" aria-label="Permalink to &quot;Config Pages&quot;">​</a></h2><p>The config pages tab shows the current config pages applied to the device.</p><p>You can remove config pages by clicking the <code>X</code> icon next to the config page name.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/nrXrJW2.png" alt="" tabindex="0"><figcaption></figcaption></figure>',27)]))}const h=i(n,[["render",r]]);export{g as __pageData,h as default};
